x_comment(x_visualQuantityDescribes,"visualQuantityDescribes relates a VisualQuantity with an entity that it describes.\n   (visualQuantityDescribes ?visual-quantity ?thing) indicates that ?thing is the object\n   that was annotated when this visual quantity was created.  For example,\n   <p>\n   <pre>\n   (visualQuantityDescribes \n      (QuantityDenotedByAnnotation \n            Object-1 \n            CarbonMassIndicator \n            (TheSet Object-2)) \n      Object-2)\n  </pre>\n  <p> is true because Object-2 is a member of the set\n  of things that are annotated by the Carbon mass indicator annotation, Object-1.") :- x_cid(a65b1328b1a8b1).
